async (b) => {
  const tiles = [];
  for (let y = 3; y <= 5; y++) for (let x = 7; x <= 9; x++) tiles.push([x, y]);
  const done = new Set();
  for (let attempt = 0; attempt < 3 && done.size < 6; attempt++) {
    for (const [x, y] of tiles) {
      if (done.has(x + "," + y)) continue;
      let r = await b.workTile(x, y, 0, "ControllerA");
      if (!r.ok) { await b.wait(200); r = await b.workTile(x, y, 0, "ControllerA"); }
      if (!r.ok) continue;
      r = await b.workTile(x, y, 2, "ControllerA");
      if (!r.ok) { await b.wait(200); r = await b.workTile(x, y, 2, "ControllerA"); }
      if (!r.ok) continue;
      r = await b.workTile(x, y, 1, "ControllerA");
      if (!r.ok) { await b.wait(200); r = await b.workTile(x, y, 1, "ControllerA"); }
      if (!r.ok) continue;
      done.add(x + "," + y);
    }
  }
  return done.size >= 6;
}
